mapper.select:
WITH current_documents AS (
    SELECT DISTINCT ON (kind) id, kind, required FROM consent_document
    WHERE kind IN ('TERMS','PRIVACY') AND effective_from <= (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date
    ORDER BY kind, effective_from DESC, created_at DESC, id DESC
)
SELECT (SELECT count(*) FROM current_documents)=2 AND NOT EXISTS (
    SELECT 1 FROM current_documents d WHERE d.required AND NOT EXISTS (
        SELECT 1 FROM consent c WHERE c.document_id=d.id AND c.subject_user_id=#{userId}
        AND c.student_id IS NULL AND c.agreed AND c.status='AGREED' AND c.withdrawn_at IS NULL
    )
)
